    [productId: "PROD-D", binLocation: "Aisle 1, Bin B04", quantity: 2],
    [productId: "PROD-B", binLocation: "Aisle 3, Bin C19", quantity: 10],
    [productId: "PROD-C", binLocation: "Aisle 4, Bin A01", quantity: 1]
